const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

const rawJid = input.body.data.key.remoteJid || '';
const senderNumber = rawJid.replace('@s.whatsapp.net', '').replace('@g.us', '').replace('@lid', '');
const senderName = input.body.data.pushName || senderNumber;
const messageText = (input.body.data.message?.conversation
  || input.body.data.message?.extendedTextMessage?.text
  || input.body.data.message?.imageMessage?.caption
  || '[Medya]').trim();

const messageId = String(input.body.data.key.id || '');
const fromMe = input.body.data.key.fromMe === true;
const now = Date.now();
const maxMessages = 30;

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};
if (!staticData._seenMessageIds) staticData._seenMessageIds = {};

// Deduplication Check (TTL + Size Limit)
if (messageId && staticData._seenMessageIds[messageId]) {
  return [{ json: { _action: 'ignore', reason: 'duplicate_message', messageId } }];
}
if (messageId) {
  staticData._seenMessageIds[messageId] = now;
  const seenTtlMs = 6 * 60 * 60 * 1000; // 6 saat TTL
  for (const [id, seenAt] of Object.entries(staticData._seenMessageIds)) {
    if (now - Number(seenAt || 0) > seenTtlMs) delete staticData._seenMessageIds[id];
  }
  const ids = Object.keys(staticData._seenMessageIds);
  if (ids.length > 3000) {
    ids.sort((a, b) => staticData._seenMessageIds[a] - staticData._seenMessageIds[b])
       .slice(0, ids.length - 2500)
       .forEach(id => delete staticData._seenMessageIds[id]);
  }
}

// === ++/-- KOMUTLARI: HER ZAMAN KOMUT OLARAK ISLE ===
if (messageText === '++') {
  staticData._manualModes[senderNumber] = true;
  delete staticData._batches[senderNumber];
  return [{ json: {
    _action: 'command',
    senderNumber: senderNumber,
    command: 'paused',
    bildirim: 'Sistem Manuel De - ' + senderName + ' (' + senderNumber + ')'
  }}];
}

if (messageText === '--') {
  staticData._manualModes[senderNumber] = false;
  return [{ json: {
    _action: 'command',
    senderNumber: senderNumber,
    command: 'resumed',
    bildirim: 'Sistem Otomatik - ' + senderName + ' (' + senderNumber + ')'
  }}];
}

if (fromMe || staticData._manualModes[senderNumber] === true) {
  return [{ json: { _action: 'ignore' } }];
}

// === BATCH TOPLAMA (State Isolation ile) ===
if (!staticData._batches[senderNumber]) {
  staticData._batches[senderNumber] = {
    pendingMessages: [],
    processingMessages: [],
    pendingStartedAt: now,
    lastMessageAt: now,
    processingStartedAt: null,
    processingToken: null,
    senderName: senderName,
    processing: false,
    hasImages: false
  };
}

const batch = staticData._batches[senderNumber];
if (!Array.isArray(batch.pendingMessages)) batch.pendingMessages = [];
if (!Array.isArray(batch.processingMessages)) batch.processingMessages = [];

if (batch.pendingMessages.length >= maxMessages) {
  return [{ json: { _action: 'spam_limit', senderNumber, senderName } }];
}

const hasImage = input.body.data.message?.imageMessage ? true : false;
if (hasImage) batch.hasImages = true;

if (!batch.pendingStartedAt || batch.pendingMessages.length === 0) {
  batch.pendingStartedAt = now;
}

batch.pendingMessages.push({
  id: messageId,
  text: messageText,
  type: hasImage ? 'image' : 'text',
  timestamp: now,
  time: new Date(now).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }),
  mediaUrl: input.body.data.message?.imageMessage?.url || null,
  mediaKey: input.body.data.message?.imageMessage?.mediaKey || null,
  mimetype: input.body.data.message?.imageMessage?.mimetype || null
});

batch.lastMessageAt = now;
batch.senderName = senderName;

// Eger işlemde degilse ve mesaj sayısı 10 ulastıysa (veya anlık işlem) process yap
const shouldProcessInstant = (!batch.processing && batch.pendingMessages.length >= 10);
return [{ json: {
  _action: shouldProcessInstant ? 'process' : (batch.processing ? 'queued_during_processing' : 'queued'),
  senderNumber,
  senderName,
  pendingCount: batch.pendingMessages.length,
  processing: batch.processing === true
}}];

const input = $input.first().json;

const allMessages  = String(input.allMessagesText || '');
const messageCount = Number(input.messageCount || 0);
const senderName   = String(input.senderName || '');

// FİLTRE KODU PATTERN TARAMASI
const codePatterns = [
  /\b(?:MANN[-\s]?)?(?:W|C|HU|WK|PU|PL)\s?\d{2,4}(?:\s?[\/\-]\s?\d{1,2})?(?:\s?[xX])?\b/gi,
  /\b(?:FILTRON[-\s]?)?(?:OP|P|OS|OW|PS|WS|AS|AP|L|LS)\s?\d{3,4}(?:\s?[\/\-]\s?\d{1,2})?\b/gi,
  /\b(?:UFI[-\s]?)?\d{2}\.\d{2}\.\d{2}(?:[\/\-]\d)?\b/gi,
  /\b(?:HENGST[-\s]?)?E\s?\d{1,2}[A-Z]\s?D?\s?\d{2,3}[A-Z]?\b/gi,
  /\b(?:PURFLUX[-\s]?)?LS\s?\d{3,4}(?:[\/\-]\d{1,2})?\b/gi,
  /\b(?:MAHLE[-\s]?)?(?:OX|OC|KC|KL|KX|PI|LS|W)\s?\d{2,4}[A-Z]?\b/gi,
  /\b(?:FILTORQ[-\s]?)?[A-Z]{1,3}\s?\d{3,4}(?:[\/\-]\d{1,2})?\b/gi,
  /\b\d{3,4}\s?[\/\-]\s?\d{1,2}\b/g
];

const detectedCodes = [];
const seen = new Set();
for (const pattern of codePatterns) {
  pattern.lastIndex = 0;
  let match;
  while ((match = pattern.exec(allMessages)) !== null) {
    const code = match[0].trim().toUpperCase();
    if (!seen.has(code) && code.length >= 4) {
      seen.add(code);
      detectedCodes.push(code);
    }
  }
}

// ARAÇ VE VIN TARAMASI
const vehicleHints = [];
const msgLower = allMessages.toLowerCase();
const vehicleKeywords = ['fiat','volkswagen','vw','renault','ford','toyota','hyundai','opel','peugeot','citroen','bmw','mercedes','audi','seat','skoda','egea','doblo','golf','passat','polo','clio','megane','tdi','multijet','dci','1.3','1.6','1.4','2010','2011','2012','2013','2014','2015','2016','2017','2018','2019','2020','2021','2022','2023'];
for (const kw of vehicleKeywords) {
  if (msgLower.includes(kw)) vehicleHints.push(kw);
}
const vinPattern = /\b[A-HJ-NPR-Z0-9]{17}\b/gi;
const detectedVINs = [];
let vinMatch;
while ((vinMatch = vinPattern.exec(allMessages)) !== null) {
  detectedVINs.push(vinMatch[0].toUpperCase());
}

let prompt = '═══ BAĞLAM BİLGİSİ (Sistem Taraması) ═══\n' +
  'Müşteri adı: ' + senderName + '\n' +
  'Batch mesaj sayısı: ' + messageCount + '\n';
if (detectedCodes.length > 0) prompt += '⚠️ TESPİT EDİLEN FİLTRE KODLARI: ' + detectedCodes.join(', ') + '\n';
if (detectedVINs.length > 0) prompt += '🔑 TESPİT EDİLEN ŞASİ NUMARASI: ' + detectedVINs.join(', ') + '\n';
if (vehicleHints.length > 0) prompt += '🚗 ARAÇ İPUCU KELİMELERİ: ' + [...new Set(vehicleHints)].join(', ') + '\n';
if (input.hasImages) prompt += '📸 MÜŞTERİ GÖRSEL GÖNDERDİ: Lütfen görselden okunan parça kodunu (varsa) codeStatus: "uncertain" ve source: "vision" olarak işaretle.\n';
prompt += '═══════════════════════════════════════\n\n';
prompt += 'Yeni müşteri mesajları:\n' + allMessages;

return [{
  json: {
    senderNumber: input.senderNumber,
    senderName: input.senderName,
    allMessagesText: input.allMessagesText,
    messageCount: input.messageCount,
    batchToken: input.batchToken,
    detectedCodes,
    detectedVINs,
    hasImages: input.hasImages || false,
    _prompt: prompt
  }
}];

const staticData = $getWorkflowStaticData('global');
const aiOutput = String($input.first().json?.output || '');

let senderNumber = '';
let senderName = '';
let allMessagesText = '';
let batchToken = '';
try {
  const sc = $('Store Context').item.json;
  senderNumber = String(sc.senderNumber || '');
  senderName = String(sc.senderName || senderNumber || 'Bilinmeyen müşteri');
  allMessagesText = String(sc.allMessagesText || '');
  batchToken = String(sc.batchToken || '');
} catch(e) {}

if (!staticData._unclearCounts) staticData._unclearCounts = {};
if (!staticData._batches) staticData._batches = {};
if (!staticData._adminNotifications) staticData._adminNotifications = {};

const batch = staticData._batches[senderNumber];
const validClaim = Boolean(batch && batch.processing === true && batch.processingToken === batchToken);

if (!validClaim && senderNumber) {
  return [{ json: {
    senderNumber, senderName, batchToken, action: 'ignore', intent: 'other', caseType: 'other',
    cevap: '', missingFields: [], confidence: 0, handoffReason: 'Geçersiz veya süresi dolmuş işlem yutuldu',
    notifyAdmins: false, validClaim: false, bildirim: ''
  }}];
}

let parsed = null;
try {
  const cleaned = aiOutput.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e1) {
  try {
    const match = aiOutput.match(/\{[\s\S]*\}/);
    if (match) parsed = JSON.parse(match[0]);
  } catch(e2) {}
}

if (!parsed) {
  return [{ json: {
    senderNumber, senderName, batchToken, action: 'handoff', intent: 'unclear', caseType: 'unclear',
    cevap: 'Talebinizi ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.',
    missingFields: [], confidence: 0, handoffReason: 'AI JSON ayrıştırma hatası',
    notifyAdmins: true, validClaim: true, pauseAutomation: true,
    bildirim: `⚠️ AI ÇIKTISI AYRIŞTIRILAMADI\nMüşteri: ${senderName} (${senderNumber})\nMesaj: ${allMessagesText}`
  }}];
}

const intent = String(parsed.intent || 'other').trim();
const caseType = String(parsed.caseType || intent || 'other').trim();
const entities = parsed.entities || {};
let replyDraft = String(parsed.replyDraft || parsed.reply || parsed.cevap || '').trim();
const missingFields = Array.isArray(parsed.missingFields) ? parsed.missingFields.slice(0, 10) : [];
const verification = parsed.verification || {};

// ═══════════════════════════════════════════════════════════════
// DÜZELTME 1: CONFİDENCE — İKİ TİP DESTEĞİ (number + object)
// ═══════════════════════════════════════════════════════════════
let confidenceValue = 0;
const rawConfidence = parsed.confidence;
if (typeof rawConfidence === 'number' && Number.isFinite(rawConfidence)) {
  confidenceValue = rawConfidence;
} else if (typeof rawConfidence === 'object' && rawConfidence !== null) {
  const vals = [
    Number(rawConfidence.intent || 0),
    Number(rawConfidence.caseType || 0),
    Number(rawConfidence.entityExtraction || 0)
  ].filter(v => Number.isFinite(v));
  confidenceValue = vals.length > 0 ? Math.min(...vals) : 0;
}
confidenceValue = Math.max(0, Math.min(1, confidenceValue));

// ═══════════════════════════════════════════════════════════════
// LAYER 2 GUARDRAIL: PROVENANCE & HALÜSİNASYON INTERCEPTOR
// DÜZELTME 2: Genişletilmiş pattern'lar
// ═══════════════════════════════════════════════════════════════
let guardrailTriggered = false;
let triggeredRule = '';

const PRICE_PATTERN = /(?:₺\s*\d+(?:[\.,]\d+)?|\d+(?:[\.,]\d+)?\s*(?:TL|₺|TRY|Lira)|(?:fiyat[ıi]?|ücret|bedel|tutar)\s*[:=]?\s*\d{2,})/i;
const COMPAT_GUARANTEE = /(?:kesin(?:likle)?|garanti|tam(?:amen)?|net|birebir|%100|%99)\s*(?:uy(?:ar|umlu|um)|olur|uygundur|uyumludur|oturur|tak[ıi]l[ıi]r|geçer)/i;
const STOCK_GUARANTEE = /(?:stok(?:ta|larımızda|umuzda|larda)?|elimizde|depo(?:muz)?da)\s+(?:mevcut(?:tur|dur)?|var(?:dır)?|bulun(?:uyor|maktad[ıi]r)|uygun(?:dur)?|mevcuttur)/i;
const BANNED_PHRASES = ['stokta var', 'stoklarımızda mevcut', 'kesin uyar', 'uyumludur', 'birebir muadilidir', 'yerine kullanabilirsiniz'];

if (verification.priceVerified !== true && PRICE_PATTERN.test(replyDraft)) {
  guardrailTriggered = true;
  triggeredRule = 'Doğrulanmamış rakamsal fiyat/TL halüsinasyonu';
} else if (verification.stockVerified !== true || verification.compatibilityVerified !== true) {
  if (COMPAT_GUARANTEE.test(replyDraft) || STOCK_GUARANTEE.test(replyDraft)) {
    guardrailTriggered = true;
    triggeredRule = 'Yasaklı stok/uyumluluk garantisi';
  } else {
    const replyLower = replyDraft.toLocaleLowerCase('tr-TR');
    for (const phrase of BANNED_PHRASES) {
      if (replyLower.includes(phrase.toLocaleLowerCase('tr-TR'))) {
        guardrailTriggered = true;
        triggeredRule = `Yasaklı stok/uyumluluk garantisi ('${phrase}')`;
        break;
      }
    }
  }
}

if (guardrailTriggered) {
  replyDraft = 'Ürünün güncel stok, fiyat ve teknik uygunluk bilgisi yetkilimiz tarafından kontrol edilerek size iletilecektir.';
}

// ═══════════════════════════════════════════════════════════════
// JAVASCRIPT POLITIKA MOTORU (POLICY ENGINE MATRIX)
// ═══════════════════════════════════════════════════════════════
let requiresHumanAction = false;
let notifyAdmin = false;
let pauseAutomation = false;
let askVehicleInfo = false;
let action = 'reply';
let handoffReason = guardrailTriggered ? `Guardrail Müdahalesi: ${triggeredRule}` : '';

// DÜZELTME 3: Düşük Güven Kontrolü (< 0.55)
if (confidenceValue < 0.55 && intent !== 'greeting' && intent !== 'unclear') {
  requiresHumanAction = true;
  notifyAdmin = true;
  pauseAutomation = true;
  action = 'handoff';
  handoffReason = handoffReason || `Düşük güven skoru (${confidenceValue.toFixed(2)})`;
  replyDraft = 'Talebinizi ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.';
} else if (guardrailTriggered) {
  requiresHumanAction = true;
  notifyAdmin = true;
  pauseAutomation = false;
} else if (caseType === 'exact_code_price_stock') {
  requiresHumanAction = true;
  notifyAdmin = true;
  pauseAutomation = false;
  askVehicleInfo = false; // KESİNLİKLE ŞASİ İSTEME!
  if (/şasi|vin|araç model/i.test(replyDraft)) {
    replyDraft = 'İlettiğiniz parça kodları işleme alınmıştır. Güncel stok ve net fiyat yetkilimiz tarafından kontrol edilerek size iletilecektir; kaç adet istediğinizi paylaşabilir misiniz?';
  }
} else if (caseType === 'exact_code_compatibility') {
  const hasVehicles = entities.vehicles && entities.vehicles.length > 0;
  if (!hasVehicles) {
    requiresHumanAction = false;
    notifyAdmin = false;
    pauseAutomation = false;
    askVehicleInfo = true;
  } else {
    requiresHumanAction = true;
    notifyAdmin = true;
    pauseAutomation = false;
    askVehicleInfo = false;
  }
} else if (caseType === 'cross_reference') {
  requiresHumanAction = true;
  notifyAdmin = true;
  pauseAutomation = false;
  askVehicleInfo = false;
} else if (caseType === 'partial_code') {
  requiresHumanAction = false;
  notifyAdmin = false;
  pauseAutomation = false;
} else if (caseType === 'vehicle_based_search') {
  const hasVehicles = entities.vehicles && entities.vehicles.length > 0;
  if (!hasVehicles) {
    requiresHumanAction = false;
    notifyAdmin = false;
    pauseAutomation = false;
    askVehicleInfo = true;
  } else {
    requiresHumanAction = true;
    notifyAdmin = true;
    pauseAutomation = false;
  }
} else if (caseType === 'non_product' || intent === 'return_complaint' || intent === 'wholesale') {
  requiresHumanAction = true;
  notifyAdmin = true;
  pauseAutomation = true; // Şikayet, iade veya temsilci talebinde botu sustur
  action = 'handoff';
  handoffReason = `Özel durum veya temsilci talebi (${intent})`;
} else if (intent === 'unclear') {
  staticData._unclearCounts[senderNumber] = Number(staticData._unclearCounts[senderNumber] || 0) + 1;
  if (staticData._unclearCounts[senderNumber] >= 2) {
    requiresHumanAction = true;
    notifyAdmin = true;
    pauseAutomation = true;
    action = 'handoff';
    handoffReason = 'Talep 2 kez üst üste anlaşılamadı';
    replyDraft = 'Talebinizi doğru yönlendirebilmek için ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.';
  }
} else if (intent === 'greeting') {
  requiresHumanAction = false;
  notifyAdmin = false;
  pauseAutomation = false;
}

if (intent !== 'unclear') delete staticData._unclearCounts[senderNumber];

// ═══════════════════════════════════════════════════════════════
// SPAM KORUMASI, COOLDOWN VE GÜNCELLEME BİLDİRİMİ
// ═══════════════════════════════════════════════════════════════
const now = Date.now();
const lastNotif = staticData._adminNotifications[senderNumber];
let isUpdate = false;
let shouldNotifyAdmin = notifyAdmin;

// DÜZELTME 4: _adminNotifications Limit Temizliği (500 max)
const notifKeys = Object.keys(staticData._adminNotifications);
if (notifKeys.length > 500) {
  const sorted = notifKeys.sort((a, b) =>
    (staticData._adminNotifications[a].timestamp || 0) -
    (staticData._adminNotifications[b].timestamp || 0)
  );
  sorted.slice(0, sorted.length - 300).forEach(k => delete staticData._adminNotifications[k]);
}

const currentCodes = Array.isArray(entities.productCodes) ? entities.productCodes.map(c => typeof c === 'object' ? c.code || c.raw : c).filter(Boolean) : [];
const quantity = String(entities.quantity || 'Belirtilmedi');

if (notifyAdmin && lastNotif && (now - Number(lastNotif.timestamp) < 3 * 60 * 1000)) {
  const oldCodes = lastNotif.codes || [];
  const addedCodes = currentCodes.filter(c => !oldCodes.includes(c));
  const qtyChanged = lastNotif.quantity !== quantity && quantity !== 'Belirtilmedi';
  if (addedCodes.length > 0 || qtyChanged || caseType !== lastNotif.caseType) {
    isUpdate = true;
    shouldNotifyAdmin = true;
  } else {
    shouldNotifyAdmin = false; // 3 dk içindeki aynen mükerrer bildirimleri engelle
  }
}

if (notifyAdmin && shouldNotifyAdmin) {
  staticData._adminNotifications[senderNumber] = {
    timestamp: now,
    caseType,
    codes: currentCodes,
    quantity
  };
}

// ═══════════════════════════════════════════════════════════════
// DİNAMİK YÖNETİCİ BİLDİRİM ŞABLONU INŞASI
// ═══════════════════════════════════════════════════════════════
let headerTitle = '📢 MÜŞTERİ TALEBİ / BİLDİRİM';
let yetkiliAksiyonu = 'Talep inceleme ve dönüş yapma';
if (isUpdate) {
  headerTitle = '🔄 SATIŞ TALEBİ GÜNCELLENDİ';
} else if (caseType === 'exact_code_price_stock' || currentCodes.length > 0) {
  headerTitle = '🔥 YÜKSEK NİYETLİ SATIŞ TALEBİ';
  yetkiliAksiyonu = 'Stok ve net fiyat kontrolü';
} else if (caseType === 'exact_code_compatibility' || intent === 'product_compatibility') {
  headerTitle = '🛠️ UYUMLULUK VE PARÇA KONTROLÜ';
  yetkiliAksiyonu = 'Şasi/Araç uyumluluk teyidi ve parça tespiti';
} else if (intent === 'return_complaint' || caseType === 'non_product') {
  headerTitle = '⚠️ ŞİKAYET / İADE / TEMSİLCİ TALEBİ';
  yetkiliAksiyonu = 'Müşteri memnuniyeti / İade prosedürü kontrolü';
}

const formattedCodes = currentCodes.length > 0 ? currentCodes.map(c => `• ${c}`).join(' ') : 'Belirtilmedi';
const formattedVehicles = Array.isArray(entities.vehicles) && entities.vehicles.length > 0 ? entities.vehicles.map(v => typeof v === 'object' ? `• ${v.brand || ''} ${v.model || ''} ${v.year || ''}`.trim() : `• ${v}`).join(' ') : (caseType === 'exact_code_price_stock' ? 'Gerekli değil (Tam kod verildi)' : 'Belirtilmedi');

const bildirim = `${headerTitle}\n` +
  `Müşteri: ${senderName} (${senderNumber})\n` +
  `Talep türü: ${caseType}\n` +
  `Kodlar: ${formattedCodes}\n` +
  `Miktar: ${quantity}\n` +
  `Araç bilgisi: ${formattedVehicles}\n` +
  `Yetkili aksiyonu: ${yetkiliAksiyonu}\n\n` +
  `📌 AI Özeti: ${allMessagesText.replace(/\s+/g, ' ').slice(0, 160)}\n` +
  `🤖 AI Cevabı: ${replyDraft}`;

return [{
  json: {
    senderNumber,
    senderName,
    batchToken,
    action,
    intent,
    caseType,
    entities,
    cevap: replyDraft,
    bildirim,
    missingFields,
    handoffReason,
    requiresHumanAction,
    pauseAutomation,
    notifyAdmins: shouldNotifyAdmin === true,
    validClaim: true
  }
}];

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const senderNumber = String(input.senderNumber || '');

if (!staticData._manualModes) staticData._manualModes = {};

// Handoff veya pauseAutomation tetiklendiyse müşteriyi manuel moda kilitliyoruz
if (input.pauseAutomation === true || input.action === 'handoff') {
  staticData._manualModes[senderNumber] = true;
  staticData._manualModes = Object.assign({}, staticData._manualModes);
  if (staticData._batches && senderNumber) delete staticData._batches[senderNumber];
} else if (staticData._batches && staticData._batches[senderNumber]) {
  const batch = staticData._batches[senderNumber];
  batch.processingMessages = [];
  batch.processing = false;
  batch.processingToken = null;
  batch.processingStartedAt = null;
  if (!Array.isArray(batch.pendingMessages) || batch.pendingMessages.length === 0) {
    delete staticData._batches[senderNumber];
  }
}

// DÜZELTME 5: _lastReply kaydı (Idle Timeout Check için)
if (input.action === 'reply' && input.expectsReply !== false && senderNumber) {
  if (!staticData._lastReply) staticData._lastReply = {};
  staticData._lastReply[senderNumber] = Date.now();
}

return [{ json: input }];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();

const IDLE_WINDOW_MS     = 35 * 1000;      // 35 sn sessizlik -> hemen işle
const MAX_WAIT_MS        = 60 * 1000;      // 60 sn toplam max bekleme
const PROCESSING_TIMEOUT = 2 * 60 * 1000;  // 2 dk AI işlem timeout recovery

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};

const ready = [];

for (const [number, rawBatch] of Object.entries(staticData._batches)) {
  const batch = rawBatch || {};
  if (!Array.isArray(batch.pendingMessages)) batch.pendingMessages = Array.isArray(batch.messages) ? batch.messages : [];
  if (!Array.isArray(batch.processingMessages)) batch.processingMessages = [];
  delete batch.messages;

  if (staticData._manualModes[number] === true) {
    delete staticData._batches[number];
    continue;
  }

  // Yarım kalan AI işlemini yeniden kuyruğa al
  if (batch.processing === true && batch.processingStartedAt && (now - Number(batch.processingStartedAt) > PROCESSING_TIMEOUT)) {
    batch.pendingMessages = [...batch.processingMessages, ...batch.pendingMessages];
    batch.processingMessages = [];
    batch.processing = false;
    batch.processingStartedAt = null;
    batch.processingToken = null;
  }

  if (batch.processing === true) continue;
  if (!batch.pendingMessages.length) {
    delete staticData._batches[number];
    continue;
  }

  const lastTime  = Number(batch.lastMessageAt || batch.lastMessageTime || now);
  const startTime = Number(batch.pendingStartedAt || batch.startTime || now);
  const idleTime  = now - lastTime;
  const totalTime = now - startTime;

  const isIdleReady      = idleTime >= IDLE_WINDOW_MS;
  const isMaxTimeReached = totalTime >= MAX_WAIT_MS;

  if (isIdleReady || isMaxTimeReached) {
    ready.push({ number, lastTime, batch, triggeredBy: isIdleReady ? 'idle' : 'max_time' });
  }
}

ready.sort((a, b) => a.lastTime - b.lastTime);
const selected = ready[0];

if (!selected) {
  return [{ json: { senderNumber: '', messageCount: 0, _ready: false } }];
}

const { number, batch } = selected;
const processingMessages = batch.pendingMessages.splice(0);
const processingToken = number + '-' + now + '-' + Math.random().toString(36).slice(2, 10);

batch.processingMessages = processingMessages;
batch.processing = true;
batch.processingStartedAt = now;
batch.processingToken = processingToken;
batch.pendingStartedAt = null; // Sıfırla ki işlemdeyken gelen mesajlar yeni sayaç başlatsın

const allMessagesText = processingMessages
  .map((message, index) => `${index + 1}. [${message.time || ''}] ${message.text}`)
  .join('\n');

const hasImages = processingMessages.some(m => m.type === 'image');
const imageMessages = processingMessages
  .filter(m => m.type === 'image' && m.mediaUrl)
  .map(m => ({ mediaUrl: m.mediaUrl, mediaKey: m.mediaKey, mimetype: m.mimetype }));

return [{
  json: {
    _ready: true,
    senderNumber: number,
    senderName: batch.senderName || number,
    messageCount: processingMessages.length,
    allMessagesText,
    batchToken: processingToken,
    hasImages,
    imageMessages
  }
}];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const idleAlertMs = 10 * 60 * 1000;

if (!staticData._lastReply) staticData._lastReply = {};
const alerts = [];
for (const [number, lastReplyTime] of Object.entries(staticData._lastReply)) {
  if (now - lastReplyTime >= idleAlertMs) {
    alerts.push({
      json: {
        senderNumber: number,
        bildirim: `Sessiz müşteri - ${number} - 10 dakikadır yanıt vermiyor`,
        _idleAlert: true
      }
    });
    delete staticData._lastReply[number];
  }
}
if (alerts.length === 0) return [{ json: { _idleAlert: false } }];
return alerts;
